files.content:
using Gtk 4.0;

template $NautilusAppChooserWidget: Widget {
  Overlay overlay {
    child: ScrolledWindow scrolled_window {
      max-content-width: 400;
      max-content-height: 300;
      hscrollbar-policy: never;
      has-frame: true;

      child: ListView program_list {
        tab-behavior: item;
      };
    };

    [overlay]
    Box no_apps {
      visible: false;
      orientation: vertical;
      halign: center;
      valign: center;

      Image {
        icon-name: "application-x-executable-symbolic";
        pixel-size: 48;
        margin-start: 12;
        margin-end: 12;
        margin-top: 12;
        margin-bottom: 12;

        styles [
          "dim-label",
        ]
      }

      Label no_apps_label {
        label: _("No applications found.");
        halign: center;
        valign: center;
        wrap: true;
        attributes: "0 -1 scale 1.2";

        styles [
          "dim-label",
        ]
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $NautilusAppChooser: Adw.Dialog {
  title: _("Open File");
  content-width: 420;
  content-height: 560;
  default-widget: ok_button;
  focus-widget: search_entry;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button cancel_button {
        label: _("_Cancel");
        use-underline: true;
        can-shrink: true;
        clicked => $adw_dialog_close(template);
      }

      [end]
      Button ok_button {
        label: _("_Open");
        use-underline: true;
        can-shrink: true;
        sensitive: false;
        activate => $open_cb(template);
        clicked => $open_cb(template);

        styles [
          "suggested-action",
        ]
      }
    }

    [top]
    Adw.Bin {
      styles [
        "toolbar",
      ]

      child: SearchEntry search_entry {
        activates-default: true;

      };
    }

    content: Adw.Clamp {
      margin-top: 18;
      margin-bottom: 18;
      margin-start: 18;
      margin-end: 18;

      child: Box content_box {
        orientation: vertical;
        spacing: 12;

        Label label_description {
          wrap: true;
          wrap-mode: word_char;
          justify: center;
          label: _("Choose an app to open the selected files");
        }
      };
    };

    [bottom]
    ListBox set_default_list_box {
      selection-mode: none;

      Adw.SwitchRow set_default_row {
        title: _("Always use for this file type");
      }

      styles [
        "background",
      ]
    }
  };
}

using Gtk 4.0;
using Adw 1;
using Gio 2.0;

menu add_tag_menu {
  section {
    label: _("Automatic Numbers");

    item {
      label: _("1, 2, 3, 4");
      action: "dialog.add-numbering-no-zero-pad-tag";
    }

    item {
      label: _("01, 02, 03, 04");
      action: "dialog.add-numbering-one-zero-pad-tag";
    }

    item {
      label: _("001, 002, 003, 004");
      action: "dialog.add-numbering-two-zero-pad-tag";
    }
  }

  section {
    label: _("Metadata");

    item {
      label: _("Creation Date");
      action: "dialog.add-creation-date-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Camera Model");
      action: "dialog.add-equipment-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Season Number");
      action: "dialog.add-season-number-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Episode Number");
      action: "dialog.add-episode-number-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Track Number");
      action: "dialog.add-track-number-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Artist Name");
      action: "dialog.add-artist-name-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Title");
      action: "dialog.add-title-tag";
      hidden-when: "action-disabled";
    }

    item {
      label: _("Album Name");
      action: "dialog.add-album-name-tag";
      hidden-when: "action-disabled";
    }
  }

  section {
    item {
      label: _("Original File Name");
      action: "dialog.add-original-file-name-tag";
    }
  }
}

menu numbering_order_menu {
  section {
    item {
      label: _("Original Name (Ascending)");
      action: "dialog.numbering-order-changed";
      target: "name-ascending";
    }

    item {
      label: _("Original Name (Descending)");
      action: "dialog.numbering-order-changed";
      target: "name-descending";
    }

    item {
      label: _("First Modified");
      action: "dialog.numbering-order-changed";
      target: "first-modified";
    }

    item {
      label: _("Last Modified");
      action: "dialog.numbering-order-changed";
      target: "last-modified";
    }
  }
}

template $NautilusBatchRenameDialog: Adw.Dialog {
  width-request: 360;
  height-request: 300;
  content-height: 600;
  content-width: 600;

  Adw.Breakpoint narrow_breakpoint {
    condition ("max-width: 480sp")

    setters {
      stack_switcher.halign: start;
      stack_switcher.orientation: vertical;
      numbering_box.orientation: vertical;
    }
  }

  child: Adw.ToolbarView toolbar_view {
    reveal-bottom-bars: false;
    bottom-bar-style: raised;

    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("_Cancel");
        use-underline: true;
        clicked => $batch_rename_dialog_on_cancel() swapped;
      }

      [end]
      Button rename_button {
        label: _("_Rename");
        use-underline: true;
        clicked => $prepare_batch_rename() swapped;

        styles [
          "suggested-action",
        ]
      }
    }

    content: Box {
      Box {
        orientation: vertical;
        spacing: 6;
        hexpand: true;

        Box stack_switcher {
          orientation: horizontal;
          spacing: 12;
          hexpand: true;
          halign: center;
          margin-top: 18;
          margin-bottom: 18;
          margin-start: 12;
          margin-end: 12;

          CheckButton format_mode_button {
            label: _("Rename _using a template");
            use-underline: true;
            active: true;
            toggled => $batch_rename_dialog_mode_changed() swapped;
          }

          CheckButton replace_mode_button {
            label: _("Find and replace _text");
            use-underline: true;
            group: format_mode_button;
            toggled => $batch_rename_dialog_mode_changed() swapped;
          }
        }

        Stack mode_stack {
          vhomogeneous: false;
          hhomogeneous: true;
          transition-type: crossfade;
          transition-duration: 100;

          StackPage {
            name: "format";

            /* Translators: Translators: This is a noun, not a verb */
            title: _("Format");

            child: Box {
              orientation: vertical;
              margin-start: 18;
              margin-end: 18;
              margin-bottom: 12;
              spacing: 12;

              Adw.Clamp {
                child: Box {
                  Entry name_entry {
                    hexpand: true;
                    activates-default: true;
                    activate => $file_names_widget_on_activate() swapped;
                  }

                  MenuButton {
                    menu-model: add_tag_menu;

                    child: Adw.ButtonContent {
                      icon-name: "list-add-symbolic";
                      label: _("Add");
                    };
                  }

                  styles [
                    "linked",
                  ]
                };
              }

              Revealer numbering_revealer {
                halign: center;

                child: Box numbering_box {
                  orientation: horizontal;
                  spacing: 12;

                  Label numbering_label {
                    label: _("Automatic Numbering Order");
                  }

                  MenuButton numbering_order_button {
                    label: _("Original Name (Ascending)");
                    menu-model: numbering_order_menu;
                    always-show-arrow: true;
                  }
                };
              }
            };
          }

          StackPage {
            name: "replace";
            title: C_("title", "Replace");

            child: Adw.Clamp {
              child: Grid replace_stack_child {
                margin-start: 18;
                margin-end: 18;
                margin-bottom: 12;
                hexpand: true;
                row-spacing: 12;
                column-spacing: 6;

                Label existing_text_label {
                  label: _("Existing Text");
                  sensitive: false;

                  layout {
                    column: "0";
                    row: "0";
                  }
                }

                Entry find_entry {
                  hexpand: true;
                  activates-default: true;
                  changed => $file_names_widget_entry_on_changed() swapped;
                  activate => $file_names_widget_on_activate() swapped;

                  layout {
                    column: "1";
                    row: "0";
                    column-span: "3";
                  }

                  accessibility {
                    labelled-by: [
                      existing_text_label,
                    ];
                  }
                }

                Label replace_label {
                  label: _("Replace With");
                  sensitive: false;

                  layout {
                    column: "0";
                    row: "1";
                  }
                }

                Entry replace_entry {
                  hexpand: true;
                  changed => $file_names_widget_entry_on_changed() swapped;
                  activate => $file_names_widget_on_activate() swapped;

                  layout {
                    column: "1";
                    row: "1";
                    column-span: "3";
                  }

                  accessibility {
                    labelled-by: [
                      replace_label,
                    ];
                  }
                }
              };
            };
          }
        }

        ScrolledWindow scrolled_window {
          hexpand: false;
          vexpand: true;
          max-content-height: 300;
          min-content-height: 240;
          max-content-width: 600;
          min-content-width: 360;

          styles [
            "batch-rename-preview",
          ]

          child: ListView batch_listview {
            factory: BuilderListItemFactory {
              template ListItem {
                child: Box batch_row {
                  orientation: bind $batch_row_orientation(
                    template.item as <ListItem>
                      .item as <$NautilusBatchRenameItem>
                      .dialog as <$NautilusBatchRenameDialog>
                      .current-breakpoint,
                    template.item as <$NautilusBatchRenameItem>.dialog
                    ) as <Orientation>;
                  spacing: 6;
                  css-classes: bind $batch_row_conflict_css_name(
                    template.item as <$NautilusBatchRenameItem>.has-conflict
                    ) as <$GStrv>;

                  Label original_name_label {
                    hexpand: true;
                    xalign: 0;
                    use-markup: true;
                    ellipsize: end;
                    label: bind template.item as <$NautilusBatchRenameItem>.name-before;
                    tooltip-markup: bind template.item as <$NautilusBatchRenameItem>.name-before;
                  }

                  Box {
                    orientation: horizontal;
                    spacing: 6;

                    Image {
                      icon-name: "arrow-next-symbolic";
                    }

                    Label result_label {
                      hexpand: true;
                      xalign: 0;
                      use-markup: true;
                      ellipsize: end;
                      label: bind template.item as <$NautilusBatchRenameItem>.name-after;
                      tooltip-markup: bind template.item as <$NautilusBatchRenameItem>.name-after;
                    }
                  }

                  SizeGroup {
                    widgets [
                      original_name_label,
                      result_label,
                    ]
                  }
                };
              }
            };

            show-separators: true;

            model: NoSelection {
              model: Gio.ListStore batch_listmodel {
                item-type: typeof<$NautilusBatchRenameItem>;
              };
            };
          };
        }
      }
    };

    [bottom]
    Box {
      styles [
        "toolbar",
      ]

      Label conflict_label {
        hexpand: true;
        xalign: 0;
      }

      Box {
        Button conflict_down {
          icon-name: "go-down-symbolic";
          tooltip-text: _("Next Conflict");
          clicked => $select_next_conflict_down() swapped;

          styles [
            "flat",
          ]
        }

        Button conflict_up {
          icon-name: "go-up-symbolic";
          tooltip-text: _("Previous Conflict");
          clicked => $select_next_conflict_up() swapped;

          styles [
            "flat",
          ]
        }
      }
    }
  };
}

using Gtk 4.0;
using Adw 1;

template $NautilusColumnChooser: Adw.Dialog {
  content-width: 360;
  content-height: 480;
  can-close: false;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      title-widget: Adw.WindowTitle window_title {
        title: _("Visible Columns");
      };
    }

    content: Box {
      orientation: vertical;

      Adw.Banner banner {
        title: _("This folder uses custom settings");
        button-label: _("_Revert");
        button-clicked => $use_default_clicked_callback();
      }

      Adw.PreferencesPage {
        Adw.PreferencesGroup {
          ListBox list_box {
            selection-mode: none;

            styles [
              "boxed-list",
            ]
          }
        }
      }
    };

    [bottom]
    ListBox use_custom_box {
      selection-mode: none;

      Adw.SwitchRow use_custom_row {
        hexpand: true;
        selectable: false;
        title: _("_Only Apply to Current Folder");
        use-underline: true;
      }

      styles [
        "background",
      ]
    }
  };
}

menu row_button_menu {
  section {
    item {
      label: _("Move _Up");
      action: "column-chooser.move-up";
    }

    item {
      label: _("Move _Down");
      action: "column-chooser.move-down";
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $NautilusCompressDialog: Adw.Dialog {
  title: _("Compress Files and Folders");
  content-height: 440;
  content-width: 500;
  default-widget: activation_button;
  focus-widget: name_entry;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-start-title-buttons: false;
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("_Cancel");
        use-underline: true;
        clicked => $adw_dialog_close() swapped;
      }

      [end]
      Button activation_button {
        label: _("C_ompress");
        use-underline: true;
        sensitive: bind $are_name_and_passphrase_ready(
          validator.passed,
          extension_combo_row.selected-item,
          passphrase_entry.text,
          passphrase_confirm_entry.text
          ) as <bool>;
        clicked => $nautilus_filename_validator_try_accept(validator);

        styles [
          "suggested-action",
        ]
      }
    }

    content: Adw.PreferencesPage {
      Adw.PreferencesGroup {
        Adw.EntryRow name_entry {
          title: _("Archive _Name");
          use-underline: true;
          changed => $nautilus_filename_validator_validate(validator);
          entry-activated => $on_name_entry_activated() swapped;
        }

        Revealer {
          reveal-child: bind validator.has-feedback no-sync-create;

          child: Label {
            label: bind validator.feedback-text no-sync-create;
            margin-top: 6;
            xalign: 0;

            styles [
              "warning",
              "caption",
            ]
          };
        }
      }

      Adw.PreferencesGroup {
        Adw.ComboRow extension_combo_row {
          title: _("Co_mpression Method");
          use-underline: true;
          notify::selected-item => $update_selected_format() swapped;
        }
      }

      Adw.PreferencesGroup passphrase_group {
        title: _("Encryption");
        description: _(
          "Encrypt contents of the archive with a password when the compression method supports password-protection."
        );

        Adw.PasswordEntryRow passphrase_entry {
          title: _("_Password");
          use-underline: true;
          entry-activated => $gtk_widget_grab_focus(passphrase_confirm_entry);
        }

        Adw.PasswordEntryRow passphrase_confirm_entry {
          title: _("_Confirm Password");
          use-underline: true;
          activates-default: true;
        }
      }
    };
  };
}

$NautilusFilenameValidator validator {
  new-name: bind $maybe_append_extension(name_entry.text, extension_combo_row.selected-item) as <string>;
  name-accepted => $on_name_accepted() swapped;
  notify::has-feedback => $on_feedback_changed(template);
}

using Gtk 4.0;
using Adw 1;

template $NautilusDateEntryRow: Adw.EntryRow {
  changed => $text_changed();

  [suffix]
  MenuButton {
    icon-name: "x-office-calendar-symbolic";
    tooltip-text: _("Pick Date");
    /*  direction is set, as popover doesn't properly show on Xorg otherwise */
    direction: left;
    valign: center;

    popover: Popover popover {
      child: Calendar calendar {
        day-selected => $calendar_date_selected(template);
      };
    };

    styles [
      "flat",
    ]
  }
}

using Gtk 4.0;
using Adw 1;

template $NautilusDateRangeDialog: Adw.Dialog {
  title: _("Add Date Filter");
  content-height: 362;
  content-width: 450;
  default-widget: select_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      title-widget: Adw.WindowTitle {
        title: _("Filter by Date");
      };
    }

    content: Adw.PreferencesPage {
      Adw.PreferencesGroup {
        Adw.ComboRow date_range_row {
          title: _("_Date Range");
          use-underline: true;

          /* Keep in sync with code */
          model: StringList {
            strings [
              _("Single Day"),
              _("± 1 day"),
              _("± 3 days"),
              _("± 7 days"),
              _("± 14 days"),
              _("Specify Range"),
            ]
          };

          notify::selected => $changed_range_mode() swapped;
        }
      }

      Adw.PreferencesGroup {
        $NautilusDateEntryRow single_date_row {
          title: _("_Date");
          use-underline: true;
          entry-activated => $try_confirm(template);
          notify::date-time => $update_confirm_button(template);
        }

        $NautilusDateEntryRow from_entry_row {
          title: _("Fro_m");
          use-underline: true;
          visible: bind single_date_row.visible inverted;
          entry-activated => $gtk_widget_grab_focus(to_entry_row);
          notify::date-time => $update_confirm_button(template);
        }

        $NautilusDateEntryRow to_entry_row {
          title: _("_To");
          use-underline: true;
          visible: bind single_date_row.visible inverted;
          entry-activated => $try_confirm(template);
          notify::date-time => $update_confirm_button(template);
        }
      }

      Adw.PreferencesGroup {
        Button select_button {
          label: _("_Filter");
          use-underline: true;
          margin-top: 12;
          halign: center;
          clicked => $try_confirm(template);

          styles [
            "pill",
            "suggested-action",
          ]
        }
      }
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $NautilusFileChooser: Adw.Window {
  width-request: 360;
  height-request: 348;
  default-widget: accept_button;

  content: $NautilusShortcutManager {
    child: Adw.ToastOverlay {
      child: Adw.OverlaySplitView split_view {
        max-sidebar-width: 240;
        sidebar-width-unit: px;
        sidebar-width-fraction: 0.2;

        styles [
          "view",
        ]

        sidebar: Adw.ToolbarView {
          [top]
          Adw.HeaderBar {
            [start]
            ToggleButton {
              tooltip-text: _("Search Everywhere");
              action-name: "slot.search-global";
              icon-name: "edit-find-symbolic";
            }

            title-widget: Label title_widget {
              ellipsize: end;
              wrap: false;
              single-line-mode: true;
              width-chars: 5;
              has-tooltip: true;
              label: bind template.title no-sync-create;
            };
          }

          content: $NautilusSidebar places_sidebar {
            vexpand: "true";
            window-slot: bind slot_container.child;
          };
        };

        content: Adw.ToolbarView {
          [top]
          $NautilusToolbar toolbar {
            show-history-controls: "true";
            window-slot: bind slot_container.child;
            show-new-folder-button: bind new_folder_button.visible;
            show-view-controls: bind view_controls.visible;
          }

          content: Adw.Bin slot_container {};

          [bottom]
          Adw.MultiLayoutView bottom_toolbar {
            Adw.Layout {
              name: "wide";

              content: CenterBox {
                [start]
                Box {
                  styles [
                    "toolbar",
                  ]

                  Adw.LayoutSlot {
                    id: "filter-dropdown";
                    visible: bind filters_dropdown.visible;
                  }
                }

                [center]
                Adw.LayoutSlot {
                  id: "filename-widget";
                }

                [end]
                Box {
                  styles [
                    "toolbar",
                  ]

                  Adw.LayoutSlot {
                    id: "choices-menu-button";
                    valign: center;
                    visible: bind choices_menu_button.visible;
                  }

                  Adw.LayoutSlot {
                    id: "accept-button";
                  }
                }
              };
            }

            Adw.Layout {
              name: "narrow";

              content: Box {
                orientation: vertical;

                Adw.LayoutSlot {
                  id: "filename-widget";
                  visible: bind filename_widget.visible;

                  styles [
                    "toolbar",
                    "no-bottom-padding",
                  ]
                }

                CenterBox {
                  [start]
                  Box {
                    valign: center;

                    styles [
                      "toolbar",
                    ]

                    ToggleButton {
                      active: bind split_view.show-sidebar bidirectional;
                      tooltip-text: _("Show Sidebar");
                      icon-name: "sidebar-show-symbolic";

                      ShortcutController {
                        scope: managed;

                        Shortcut {
                          trigger: "F9";
                          action: "activate";
                        }
                      }
                    }

                    Adw.LayoutSlot {
                      id: "filter-dropdown";
                      visible: bind filters_dropdown.visible;
                    }
                  }

                  [center]
                  Adw.LayoutSlot {
                    id: "accept-button";
                  }

                  [end]
                  Box {
                    valign: center;

                    styles [
                      "toolbar",
                    ]

                    Button new_folder_button {
                      visible: false;
                      icon-name: "folder-new-symbolic";
                      tooltip-text: _("New Folder");
                      action-name: "view.new-folder";
                      focus-on-click: false;
                    }

                    Adw.LayoutSlot {
                      id: "choices-menu-button";
                      visible: bind choices_menu_button.visible;
                    }

                    $NautilusViewControls view_controls {
                      window-slot: bind slot_container.child;
                    }
                  }
                }
              };
            }

            [filename-widget]
            Stack filename_widget {
              Overlay filename_button_container {
                valign: center;

                Button {
                  tooltip-text: _("Edit File Name");

                  accessibility {
                    labelled-by: [
                      filename_label,
                    ];
                  }

                  clicked => $open_filename_entry(template);

                  child: CenterBox {
                    [start]
                    Adw.Bin filename_button_start {}

                    /* Center the label and don't overlap the overlay */
                    [center]
                    Label filename_label {
                      single-line-mode: true;
                      label: bind filename_entry.text;
                      ellipsize: middle;
                    }

                    [end]
                    Image filename_button_end {
                      margin-start: 12;
                      icon-name: "document-edit-symbolic";
                    }
                  };
                }

                [overlay]
                Button filename_undo_button {
                  tooltip-text: _("Reset File Name");
                  icon-name: "edit-undo-symbolic";
                  visible: false;
                  halign: start;
                  clicked => $on_filename_undo_button_clicked(template);

                  styles [
                    "flat",
                  ]
                }
              }

              Entry filename_entry {
                tooltip-text: _("File Name");
                valign: center;
                max-width-chars: 30;
                activates-default: true;
                changed => $on_filename_entry_changed(template);

                EventControllerFocus {
                  leave => $on_filename_entry_focus_leave(template);
                }
              }
            }

            [accept-button]
            Button accept_button {
              label: "_Select";
              use-underline: true;
              margin-top: 6;
              margin-bottom: 6;
              margin-start: 6;
              margin-end: 6;
              action-name: "chooser.accept";

              styles [
                "pill",
                "suggested-action",
              ]
            }

            [choices-menu-button]
            MenuButton choices_menu_button {
              icon-name: "nautilus-file-chooser-options-symbolic";

