      StackPage {
        name: "start";

        child: Adw.StatusPage {
          icon-name: "edit-find-symbolic";
          title: _("Search File Types");
          description: _("Search by type, name, or description");
        };
      }

      StackPage {
        name: "empty";

        child: Adw.StatusPage {
          icon-name: "edit-find-symbolic";
          title: _("No Results Found");
          description: _("Try a different search");
        };
      }

      StackPage {
        name: "results";

        child: ScrolledWindow {
          ListView listview {
            show-separators: true;

            factory: BuilderListItemFactory {
              template ListItem {
                child: Box {
                  margin-start: 16;
                  margin-end: 16;
                  margin-top: 14;
                  margin-bottom: 14;
                  spacing: 12;

                  Image {
                    pixel-size: 32;
                    paintable: bind template.item as <$NautilusMinimalCell>.paintable;

                    accessibility {
                      labelled-by: [
                        description,
                      ];
                    }
                  }

                  Box {
                    orientation: vertical;
                    spacing: 4;

                    Label description {
                      halign: start;
                      hexpand: true;
                      ellipsize: end;
                      label: bind template.item as <$NautilusMinimalCell>.title;
                    }

                    Label {
                      halign: start;
                      hexpand: true;
                      ellipsize: end;
                      label: bind template.item as <$NautilusMinimalCell>.subtitle;

                      styles [
                        "caption",
                        "dim-label",
                      ]
                    }
                  }
                };
              }
            };
          }
        };
      }
    };
  };
}

