using Gtk 4.0;
using Adw 1;

template $NautilusSidebarRow: ListBoxRow {
  focus-on-click: false;

  child: Revealer revealer {
    reveal-child: true;
    notify::child-revealed => $on_child_revealed();

    styles [
      "sidebar-revealer",
    ]

    Box {
      Image start_icon_widget {
        margin-end: 8;

        accessibility {
          labelled-by: [
            label_widget,
          ];
        }
      }

      Label label_widget {
        hexpand: true;
        xalign: 0;
        ellipsize: middle;
        margin-end: 2;
      }

      Image end_icon_widget {
        visible: false;
        hexpand: true;
        halign: end;
        valign: center;
        margin-end: 8;
      }

      Button eject_button {
        halign: center;
        valign: center;
        margin-start: 4;
        icon-name: "media-eject-symbolic";

        styles [
          "sidebar-button",
        ]
      }

      Adw.Spinner busy_spinner {
        halign: center;
        valign: center;
        margin-start: 4;
        margin-end: 4;
        visible: false;
        opacity: 0.7;
      }
    }
  };
}

using Gtk 4.0;
using Adw 1;

template $NautilusToolbar: Adw.Bin {
  Adw.HeaderBar {
    [title]
    Box header_toolbar {
      spacing: 6;

      Stack toolbar_switcher {
        valign: center;
        hexpand: false;
        transition-type: crossfade;

        StackPage {
          name: "pathbar";

          child: $NautilusPathBar path_bar {
            valign: "center";
            window-slot: bind template.window-slot;
          };
        }

        StackPage {
          name: "location";

          child: Box {
            styles [
              "linked",
            ]

            $NautilusLocationEntry location_entry {}

            Button {
              icon-name: "window-close-symbolic";
              tooltip-text: _("Cancel");
              clicked => $nautilus_toolbar_close_location_entry() swapped;
            }
          };
        }

        StackPage {
          name: "search";

          child: Box search_container {
            orientation: vertical;
          };
        }
      }

      Stack search_button_stack {
        hhomogeneous: true;
        transition-type: crossfade;

        ToggleButton search_button {
          tooltip-text: _("Search Current Folder");
          halign: center;
          valign: center;
          action-name: "slot.search-visible";
          icon-name: "nautilus-folder-search-symbolic";
          active: bind template.window-slot as <$NautilusWindowSlot>.search-visible;
        }

        Adw.Bin search_button_placeholder {}
      }
    }

    [start]
    ToggleButton show_sidebar_button {
      visible: bind template.show-sidebar-button bidirectional;
      active: bind template.sidebar-button-active bidirectional;
      tooltip-text: _("Show Sidebar");
      icon-name: "sidebar-show-symbolic";
    }

    [start]
    Stack history_controls_stack {
      visible: bind template.show-history-controls;
      hhomogeneous: true;
      transition-type: crossfade;

      $NautilusHistoryControls history_controls {
        window-slot: bind template.window-slot;
      }

      Adw.Bin history_controls_placeholder {}
    }

    [end]
    $NautilusViewControls {
      visible: bind template.show-view-controls;
      window-slot: bind template.window-slot;
    }

    [end]
    Button new_folder_button {
      visible: bind template.show-new-folder-button;
      icon-name: "folder-new-symbolic";
      tooltip-text: _("New Folder");
      action-name: "view.new-folder";
      focus-on-click: false;
    }
  }
}

using Gtk 4.0;
using Adw 1;

menu view_menu {
  section {
    label: _("Icon Size");
    display-hint: "inline-buttons";

    item {
      custom: "zoom-out";
    }

    item {
      custom: "zoom-in";
    }
  }

  section {
    /* Sort section. The toolbar code assumes this is the second item of this
     * menu model. Its contents is provided by the view.
     */
    /* Translators: a menu item in a group of sorting options in a toolbar menu, with criterions such as "A-Z" or "Last Modified". */
    label: C_("menu item", "Sort");
  }

  section {
    item {
      label: _("Show _Hidden Files");
      action: "view.show-hidden-files";
      accel: "<control>h";
    }
  }

  section {
    item {
      label: _("_Visible Columns…");
      action: "view.visible-columns";
      hidden-when: "action-disabled";
    }
  }

  section {
    item {
      label: _("Captions…");
      action: "view.visible-captions";
      hidden-when: "action-disabled";
    }
  }
}

template $NautilusViewControls: Adw.Bin {
  child: Adw.SplitButton view_split_button {
    halign: center;
    valign: center;

    /* Translators: This is a noun, meaning the options pertaining to the view. */
    dropdown-tooltip: _("View Options");
    action-name: "slot.files-view-mode-toggle";

    popover: PopoverMenu {
      menu-model: view_menu;

      [zoom-out]
      Button {
        icon-name: "zoom-out-symbolic";
        action-name: "view.zoom-out";
        tooltip-text: _("Zoom Out");

        styles [
          "flat",
        ]
      }

      [zoom-in]
      Button {
        icon-name: "zoom-in-symbolic";
        action-name: "view.zoom-in";
        tooltip-text: _("Zoom In");

        styles [
          "flat",
        ]
      }
    };

    icon-name: bind template.window-slot as <$NautilusWindowSlot>.icon-name;
    tooltip-text: bind template.window-slot as <$NautilusWindowSlot>.tooltip;
  };
}

